insert into public.game_section_settings(id,label,short_label,icon,description,enabled,sort_order) values ('dungeons','Dungeons','Dungeons','⚔','The full 1,500-room dungeon rebalance.',true,100),('workbench','Workbench','Workbench','⚒','Dungeon recipe workbench using essence and forge materials.',true,120) on conflict(id) do update set label=excluded.label,short_label=excluded.short_label,icon=excluded.icon,description=excluded.description,enabled=true;
   insert into public.player_dungeon_materials(player_id,material_name,quantity,updated_at) values(p_player_id,v_item->>'name',v_count,now())
   insert into public.dungeon_gear(player_id,room_number,source_enemy,item_type,quality,upgrade_level,gem_power,mutation_name,stats)
   insert into public.player_dungeon_essence(player_id,essence_tier,quantity,updated_at) values(p_player_id,v_item->>'tier',v_count,now())
