-- PR #507: SQL-editor alternative to the FIRST migration only.
-- Keep maintenance enabled. Run numbered files in order; wait for a success result.
begin;
do $$ begin
  if (select count(*) from public.dungeon_catalog_rooms where room_number between 1 and 1500) <> 1500 then
    raise exception 'All 1500 rooms must be imported before this step';
  end if;
end $$;
on conflict(room_number) do update set boss_name=excluded.boss_name,zone_rating=excluded.zone_rating,rating_used=excluded.rating_used,repeat_bonus=excluded.repeat_bonus;
on conflict(id) do update set name=excluded.name,source=excluded.source,slot=excluded.slot,gem_power=excluded.gem_power,used_in=excluded.used_in;
on conflict(name) do update set tier=excluded.tier,value_multiplier=excluded.value_multiplier,native_regions=excluded.native_regions,best_odds=excluded.best_odds,shard_gem_power=excluded.shard_gem_power,core_gem_power=excluded.core_gem_power;
on conflict(name) do update set tier=excluded.tier,kind=excluded.kind,source=excluded.source,essence_cost=excluded.essence_cost,essence_tier=excluded.essence_tier,ingredients=excluded.ingredients,gem_power=excluded.gem_power,enabled=true;
on conflict(material_count,equipment) do update set chance=excluded.chance;
alter table public.dungeon_catalog_rooms enable row level security; alter table public.dungeon_regions enable row level security; alter table public.dungeon_difficulty_zones enable row level security; alter table public.dungeon_boss_catalog enable row level security; alter table public.dungeon_forge_materials enable row level security; alter table public.dungeon_mutations enable row level security; alter table public.dungeon_workbench_recipes enable row level security; alter table public.dungeon_equipment_crafting_chances enable row level security; alter table public.player_dungeon_materials enable row level security; alter table public.player_dungeon_essence enable row level security; alter table public.dungeon_gear enable row level security;
revoke all on public.dungeon_catalog_rooms,public.dungeon_regions,public.dungeon_difficulty_zones,public.dungeon_boss_catalog,public.dungeon_forge_materials,public.dungeon_mutations,public.dungeon_workbench_recipes,public.dungeon_equipment_crafting_chances,public.player_dungeon_materials,public.player_dungeon_essence,public.dungeon_gear from anon,authenticated;
grant select on public.dungeon_catalog_rooms,public.dungeon_regions,public.dungeon_difficulty_zones,public.dungeon_boss_catalog,public.dungeon_forge_materials,public.dungeon_mutations,public.dungeon_workbench_recipes,public.dungeon_equipment_crafting_chances to anon,authenticated; grant all on public.player_dungeon_materials,public.player_dungeon_essence,public.dungeon_gear to service_role;
drop policy if exists dungeon_catalog_public_read on public.dungeon_catalog_rooms; create policy dungeon_catalog_public_read on public.dungeon_catalog_rooms for select to anon,authenticated using (true);
drop policy if exists dungeon_regions_public_read on public.dungeon_regions; create policy dungeon_regions_public_read on public.dungeon_regions for select to anon,authenticated using (true);
drop policy if exists dungeon_zones_public_read on public.dungeon_difficulty_zones; create policy dungeon_zones_public_read on public.dungeon_difficulty_zones for select to anon,authenticated using (true);
drop policy if exists dungeon_boss_public_read on public.dungeon_boss_catalog; create policy dungeon_boss_public_read on public.dungeon_boss_catalog for select to anon,authenticated using (true);
drop policy if exists dungeon_material_public_read on public.dungeon_forge_materials; create policy dungeon_material_public_read on public.dungeon_forge_materials for select to anon,authenticated using (true);
drop policy if exists dungeon_mutation_public_read on public.dungeon_mutations; create policy dungeon_mutation_public_read on public.dungeon_mutations for select to anon,authenticated using (true);
drop policy if exists dungeon_recipe_public_read on public.dungeon_workbench_recipes; create policy dungeon_recipe_public_read on public.dungeon_workbench_recipes for select to anon,authenticated using (true);
drop policy if exists dungeon_crafting_chance_public_read on public.dungeon_equipment_crafting_chances; create policy dungeon_crafting_chance_public_read on public.dungeon_equipment_crafting_chances for select to anon,authenticated using (true);
create index if not exists dungeon_catalog_region_idx on public.dungeon_catalog_rooms(region,room_number); create index if not exists dungeon_catalog_zone_idx on public.dungeon_catalog_rooms(zone,room_number); create index if not exists dungeon_gear_player_idx on public.dungeon_gear(player_id,created_at desc);

create or replace function public.claim_dungeon_run_rewards(p_run_id uuid,p_player_id uuid) returns jsonb language plpgsql security definer set search_path=public as $$
declare v_run public.dungeon_runs%rowtype; v_item jsonb; v_count bigint; v_materials jsonb:='[]'::jsonb; v_essence jsonb:='[]'::jsonb;
begin
 select * into v_run from public.dungeon_runs where id=p_run_id and player_id=p_player_id and status='won' for update;
 if not found then raise exception 'run_not_claimable'; end if;
 for v_item in select value from jsonb_array_elements(coalesce(v_run.loot,'[]'::jsonb)) loop
  if v_item->>'type'='material' then
   v_count:=greatest(1,coalesce((v_item->>'quantity')::bigint,1));
   on conflict(player_id,material_name) do update set quantity=public.player_dungeon_materials.quantity+excluded.quantity,updated_at=now();
   v_materials:=v_materials||jsonb_build_array(jsonb_build_object('name',v_item->>'name','quantity',v_count));
  elsif v_item->>'type'='gear' then
   values(p_player_id,coalesce((v_item->>'room')::integer,coalesce(v_run.room_number,0)),coalesce(v_item->>'source_enemy','Dungeon enemy'),coalesce(v_item->>'item_type','weapon'),coalesce(v_item->>'quality','Common'),coalesce((v_item->>'upgrade_level')::integer,0),coalesce((v_item->>'gem_power')::bigint,0),nullif(v_item->>'mutation_name',''),coalesce(v_item->'stats',jsonb_build_object('components',coalesce((v_item->>'components')::integer,0),'name',v_item->>'name')));
  elsif v_item->>'type'='essence' then
   v_count:=greatest(1,coalesce((v_item->>'quantity')::bigint,1));
   on conflict(player_id,essence_tier) do update set quantity=public.player_dungeon_essence.quantity+excluded.quantity,updated_at=now();
   v_essence:=v_essence||jsonb_build_array(jsonb_build_object('tier',v_item->>'tier','quantity',v_count));
  end if;
 end loop;
 update public.dungeon_runs set status='claimed',claimed_at=now(),updated_at=now() where id=v_run.id;
 return jsonb_build_object('ok',true,'materials',v_materials,'essence',v_essence,'loot',v_run.loot,'runId',v_run.id);
end; $$;
revoke all on function public.claim_dungeon_run_rewards(uuid,uuid) from public,anon,authenticated; grant execute on function public.claim_dungeon_run_rewards(uuid,uuid) to service_role;

create or replace function public.craft_dungeon_workbench(p_player_id uuid,p_recipe_name text) returns jsonb language plpgsql security definer set search_path=public as $$
declare r public.dungeon_workbench_recipes%rowtype; i jsonb; need bigint; have bigint; v_gear uuid; v_ess bigint; v_gp bigint; v_id text; v_total_ess bigint;
begin
 select * into r from public.dungeon_workbench_recipes where name=p_recipe_name and enabled=true;
 if not found then raise exception 'recipe_not_found'; end if;
 v_total_ess:=r.essence_cost;
 for i in select value from jsonb_array_elements(r.ingredients) loop
  if i->>'item' in ('TE','SE','LE','ME') then
   if i->>'item'=r.essence_tier then v_total_ess:=v_total_ess+greatest(1,(i->>'qty')::bigint); end if;
  end if;
 end loop;
 select quantity into v_ess from public.player_dungeon_essence where player_id=p_player_id and essence_tier=r.essence_tier for update;
 if coalesce(v_ess,0)<v_total_ess then raise exception 'insufficient_essence'; end if;
 for i in select value from jsonb_array_elements(r.ingredients) loop
  need:=greatest(1,(i->>'qty')::bigint);
  if i->>'item' in ('TE','SE','LE','ME') then continue; end if;
  select quantity into have from public.player_dungeon_materials where player_id=p_player_id and material_name=i->>'item' for update;
  if coalesce(have,0)<need then raise exception 'insufficient_material:%',(i->>'item'); end if;
 end loop;
 update public.player_dungeon_essence set quantity=quantity-v_total_ess,updated_at=now() where player_id=p_player_id and essence_tier=r.essence_tier;
 for i in select value from jsonb_array_elements(r.ingredients) loop
  if i->>'item' in ('TE','SE','LE','ME') then continue; end if;
  update public.player_dungeon_materials set quantity=quantity-greatest(1,(i->>'qty')::bigint),updated_at=now() where player_id=p_player_id and material_name=i->>'item';
 end loop;
 v_gp:=r.gem_power; v_id:=lower(regexp_replace(r.name,'[^a-zA-Z0-9]+','-','g'));
 return jsonb_build_object('ok',true,'recipe',r.name,'gemPower',v_gp,'gearId',v_gear);
end; $$;
revoke all on function public.craft_dungeon_workbench(uuid,text) from public,anon,authenticated; grant execute on function public.craft_dungeon_workbench(uuid,text) to service_role;

select setval(pg_get_serial_sequence('public.dungeon_workbench_recipes','id'),coalesce((select max(id) from public.dungeon_workbench_recipes),1),true);
commit;
select '17 catalogs, functions and permissions committed' as result;
